def transform(grid):
    n=len(grid[0])
    sep=next(c for c in range(n) if c>0 and c<n-1 and len(set(row[c] for row in grid))==1)
    w=min(sep,n-sep-1)
    out=[[4]*w for _ in grid]
    for r,row in enumerate(grid):
        for c in range(w):
            if row[c] not in (8,2) and row[sep+1+c]==4:
                out[r][c]=3
    return out
